import{_ as s,o as t,c as a,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/programmierung/report-anpassen-17.png",p="/bilder/programmierung/report-anpassen-18.png",d="/bilder/programmierung/report-anpassen-19.png",l="/bilder/programmierung/report-anpassen-20.png",f=JSON.parse('{"title":"Einen Subreport dynamisch einbinden","description":"","frontmatter":{"title":"Einen Subreport dynamisch einbinden","source_pageid":1567,"source_revision":7224},"headers":[],"relativePath":"reporting/programmierung/einen-subreport-dynamisch-in-einen-report-einbinden.md","filePath":"reporting/programmierung/einen-subreport-dynamisch-in-einen-report-einbinden.md"}'),u={name:"reporting/programmierung/einen-subreport-dynamisch-in-einen-report-einbinden.md"};function c(h,i,g,m,b,S){return t(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="einen-subreport-dynamisch-einbinden" tabindex="-1">Einen Subreport dynamisch einbinden <a class="header-anchor" href="#einen-subreport-dynamisch-einbinden" aria-label="Permalink to &quot;Einen Subreport dynamisch einbinden&quot;">​</a></h1><p>Binden Sie einen wiederverwendbaren Schulkopf in einen bestehenden Report ein. Das Beispiel zeigt eine dynamische Verknüpfung und erläutert den Unterschied zum statisch eingefügten Subreport.</p><p>In diesem vertiefenden Beispiel wird ein <strong>Schulkopf</strong> in einen bestehenden Report eingebunden. Hierzu wird ein <strong>Subreport</strong> verwendet, der sich im Ordner <strong>Header_Footer</strong> befindet.</p><p>Ein <strong>Subreport</strong> ist ein eigener Report, der in einen anderen Report eingebunden wird. Dies ermöglicht es, wiederkehrende Elemente wie Briefköpfe, Schulköpfe oder Fußzeilen zentral zu pflegen.</p><h2 id="statische-und-dynamische-subreports-unterscheiden" tabindex="-1">Statische und dynamische Subreports unterscheiden <a class="header-anchor" href="#statische-und-dynamische-subreports-unterscheiden" aria-label="Permalink to &quot;Statische und dynamische Subreports unterscheiden&quot;">​</a></h2><p><a href="/bilder/programmierung/report-anpassen-17.png"><img src="'+o+`" alt="&quot;Dynamische Subreports&quot; (links) und &quot;statische Subreports&quot; (rechts)." loading="lazy"></a></p><p><em>&quot;Dynamische Subreports&quot; (links) und &quot;statische Subreports&quot; (rechts).</em></p><p>Es gibt zwei Arten von Subreports:</p><ul><li><strong>Statischer Subreport</strong></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Ein statischer Subreport wird einmalig in den Hauptreport eingefügt und dort gespeichert.  </span></span>
<span class="line"><span> Änderungen am Subreport wirken sich auf den Hauptreport nur aus, wenn dieser manuell angepasst wird.  </span></span>
<span class="line"><span> (Im Bild rechts.)</span></span></code></pre></div><ul><li><strong>Dynamisch ladbarer Subreport</strong></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Ein dynamischer Subreport wird nicht eingebettet, sondern verknüpft.  </span></span>
<span class="line"><span> Beim Erzeugen des Hauptreports wird der Subreport jedes Mal neu geladen.  </span></span>
<span class="line"><span> Änderungen im Subreport wirken daher automatisch in allen Reports, die ihn verwenden.  </span></span>
<span class="line"><span> Dies eignet sich besonders für einheitliche oder institutionell gepflegte Elemente wie Schulköpfe.  </span></span>
<span class="line"><span> (Im Bild links.)</span></span></code></pre></div>`,12),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Wird ein dynamischer Subreport in seiner Höhe verändert, kann dies in anderen Reports zu unerwünschten Layoutverschiebungen führen."),e("p",null,"Ein dynamischer Subreport sollte nach der Erstkonfiguration nur vorsichtig in seinen Abmessungen verändert werden.")],-1),r('<p><a href="/bilder/programmierung/report-anpassen-18.png"><img src="'+p+'" alt="Nutzen eines dynamischen Subreports." loading="lazy"></a></p><p><em>Nutzen eines dynamischen Subreports.</em></p><h2 id="den-schulkopf-einbinden" tabindex="-1">Den Schulkopf einbinden <a class="header-anchor" href="#den-schulkopf-einbinden" aria-label="Permalink to &quot;Den Schulkopf einbinden&quot;">​</a></h2><p>Im Beispiel wird ein <strong>dynamischer Subreport</strong> im <strong>Kopf</strong> des aktuellen Reports platziert.</p><ol><li>Wählen Sie in der Werkzeugleiste das Werkzeug für einen <strong>Subreport</strong> und platzieren Sie ihn an der gewünschten Stelle.</li><li>Klicken Sie mit der rechten Maustaste auf den eingefügten Subreport.</li><li>Wählen Sie <strong>Subreport-Datei wählen…</strong>.</li></ol>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Im Kontextmenü sollte "),e("strong",null,"Dehnen"),n(" aktiviert sein.")]),e("p",null,"Dies bedeutet, dass sich das Feld des Subreports automatisch an die Größe des Inhalts anpasst.")],-1),r('<p><a href="/bilder/programmierung/report-anpassen-19.png"><img src="'+d+'" alt="Wahl des zu verwendenden Subreports als Kopf." loading="lazy"></a></p><p><em>Wahl des zu verwendenden Subreports als Kopf.</em></p><p>Im Ordner <strong>Header_Footer</strong> wird nun der passende Kopf gewählt.</p><p><a href="/bilder/programmierung/report-anpassen-20.png"><img src="'+l+'" alt="Der Kopf erscheint über der Klassenliste." loading="lazy"></a></p><p><em>Der Kopf erscheint über der Klassenliste.</em></p><p>Der Schulkopf erscheint nun über dem aktuellen Report. Da er als <strong>dynamischer Subreport</strong> eingebunden ist, werden zukünftige Änderungen automatisch übernommen. So lassen sich Layout- oder Informationsanpassungen zentral pflegen, ohne jeden Report einzeln ändern zu müssen.</p><p>Dies ist insbesondere bei einheitlich zu haltenden Reports (z. B. Listen, Serienbriefe, Zeugnisse) sinnvoll.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einen_Subreport_dynamisch_in_einen_Report_einbinden" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7224.</p>',9)])])}const k=s(u,[["render",c]]);export{f as __pageData,k as default};
